.chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #2c3e50);
  background: var(--paper, #f9f9f9);
  padding: 2rem;
  line-height: 1.6;
}
.chapter-header h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  color: var(--ink, #2c3e50);
}
.lead {
  font-size: 1.1rem;
  color: var(--muted, #666);
  max-width: 800px;
}
.layout-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin: 2rem 0;
}
@media (max-width: 768px) {
  .layout-grid { grid-template-columns: 1fr; }
}
.visual-panel {
  background: #fff;
  border: 1px solid var(--line, #ddd);
  padding: 1rem;
  border-radius: 4px;
}
.canvas-wrapper {
  width: 100%;
  height: 300px;
  background: #f0f4f8;
  border: 1px solid #ccc;
  margin-bottom: 1rem;
  position: relative;
}
#geo-canvas {
  width: 100%;
  height: 100%;
  display: block;
}
.controls-panel {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.btn-primary {
  background: var(--accent, #3498db);
  color: #fff;
  border: none;
  padding: 0.6rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.95rem;
}
.btn-primary:hover { background: #2980b9; }
.warning-box {
  background: #ffebee;
  border-left: 4px solid #e74c3c;
  padding: 0.8rem;
  font-size: 0.9rem;
  color: #c0392b;
}
.derivation-panel {
  background: #fff;
  border: 1px solid var(--line, #ddd);
  padding: 1.5rem;
  border-radius: 4px;
}
.step-container {
  margin-bottom: 1.5rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px dashed #eee;
}
.step-container:last-child { border-bottom: none; }
.step-container h3 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
  color: var(--ink, #2c3e50);
}
.math {
  font-family: "Times New Roman", serif;
  font-style: italic;
  background: #f0f4f8;
  padding: 0 0.3rem;
  border-radius: 2px;
}
.formula-block {
  background: #f8f9fa;
  border: 1px solid #e9ecef;
  padding: 1rem;
  text-align: center;
  font-family: "Times New Roman", serif;
  margin: 0.8rem 0;
  border-radius: 4px;
}
.source-btn {
  background: transparent;
  border: 1px solid var(--accent, #3498db);
  color: var(--accent, #3498db);
  padding: 0.3rem 0.6rem;
  font-size: 0.85rem;
  border-radius: 3px;
  cursor: pointer;
  margin-right: 0.5rem;
  margin-top: 0.5rem;
}
.source-btn:hover { background: #ebf5fb; }
.evidence-section {
  margin-top: 3rem;
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--line, #ddd);
  border-radius: 4px;
}
.table-wrapper {
  overflow-x: auto;
  margin: 1rem 0;
}
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}
th, td {
  border: 1px solid #ddd;
  padding: 0.6rem;
  text-align: center;
}
th {
  background: #f8f9fa;
  font-weight: 600;
}
tr:nth-child(even) { background: #fafafa; }
.table-notes {
  font-size: 0.85rem;
  color: var(--muted, #666);
  margin-top: 0.5rem;
}
.interaction-demo {
  margin-top: 2rem;
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--line, #ddd);
  border-radius: 4px;
}
.teaching-label {
  font-size: 0.85rem;
  color: var(--muted, #666);
  font-style: italic;
  margin-bottom: 1rem;
}
.solver-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  margin-bottom: 1rem;
}
.solver-controls label {
  font-size: 0.9rem;
  font-weight: 500;
}
.solver-controls input {
  padding: 0.4rem;
  border: 1px solid #ccc;
  border-radius: 3px;
  width: 80px;
}
.result-box {
  background: #f0f4f8;
  padding: 1rem;
  border-radius: 4px;
  font-family: monospace;
  min-height: 1.5rem;
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
