(function() {
  'use strict';

  // 状态管理
  const state = {
    isLinear: false,
    sensors: [],
    a: 0, // 线性斜率
    b: 0  // 线性截距
  };

  // 初始化传感器位置
  function initSensors() {
    // 任意分布示例
    state.sensors = [
      {x: 0, y: 0},
      {x: -5, y: 8},
      {x: 4, y: 6},
      {x: -2, y: 4},
      {x: 7, y: 3}
    ];
    state.isLinear = false;
    state.a = 0;
    state.b = 0;
  }

  // 切换为线性排列
  function setLinearArray() {
    // 线性排列示例：y = 0 (x 轴)
    state.sensors = [
      {x: 0, y: 0},
      {x: -5, y: 0},
      {x: 4, y: 0},
      {x: -2, y: 0},
      {x: 7, y: 0}
    ];
    state.isLinear = true;
    state.a = 0;
    state.b = 0;
  }

  // 绘制几何图形
  function drawGeometry() {
    const canvas = document.getElementById('geo-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;

    // 清空画布
    ctx.clearRect(0, 0, w, h);

    // 设置坐标系变换
    const padding = 40;
    const scaleX = (w - 2 * padding) / 20; // 假设 x 范围 -10 到 10
    const scaleY = (h - 2 * padding) / 20; // 假设 y 范围 -10 到 10
    const originX = padding;
    const originY = h - padding;

    // 绘制坐标轴
    ctx.strokeStyle = '#ccc';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(originX, originY);
    ctx.lineTo(w - padding, originY);
    ctx.moveTo(originX, originY);
    ctx.lineTo(originX, padding);
    ctx.stroke();

    // 绘制传感器
    ctx.fillStyle = '#2c3e50';
    state.sensors.forEach((s, i) => {
      const sx = originX + s.x * scaleX;
      const sy = originY - s.y * scaleY;
      ctx.beginPath();
      ctx.arc(sx, sy, 6, 0, Math.PI * 2);
      ctx.fill();
      // 标注编号
      ctx.fillStyle = '#666';
      ctx.font = '12px sans-serif';
      ctx.fillText(`S${i+1}`, sx + 10, sy - 10);
      ctx.fillStyle = '#2c3e50';
    });

    // 如果是线性排列，绘制连线
    if (state.isLinear) {
      ctx.strokeStyle = '#e74c3c';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      const first = state.sensors[0];
      const last = state.sensors[state.sensors.length - 1];
      ctx.moveTo(originX + first.x * scaleX, originY - first.y * scaleY);
      ctx.lineTo(originX + last.x * scaleX, originY - last.y * scaleY);
      ctx.stroke();
      ctx.setLineDash([]);
    }
  }

  // 渲染表格数据
  function renderTable() {
    const tbody = document.getElementById('mse-table-body');
    if (!tbody) return;

    const tables = window.paperMindData?.tables || [];
    const tableData = tables.find(t => t.id === 'p9-TABLE_II');

    if (!tableData) {
      tbody.innerHTML = '<tr><td colspan="9">数据加载失败</td></tr>';
      return;
    }

    let html = '';
    tableData.rows.forEach(row => {
      html += `<tr>`;
      html += `<td><strong>${row.label}</strong></td>`;
      for (let m = 3; m <= 10; m++) {
        const val = row.values[`M = ${m}`];
        // 处理 null 或 非数字
        const displayVal = (val === null || val === undefined) ? '-' : val;
        html += `<td>${displayVal}</td>`;
      }
      html += `</tr>`;
    });
    tbody.innerHTML = html;
  }

  // 二次方程求解器
  function solveQuadratic() {
    const aInput = document.getElementById('coef-a');
    const eInput = document.getElementById('coef-e');
    const cInput = document.getElementById('coef-c');
    const resultBox = document.getElementById('solver-result');

    if (!aInput || !eInput || !cInput || !resultBox) return;

    const A = parseFloat(aInput.value);
    const E = parseFloat(eInput.value);
    const C = parseFloat(cInput.value);

    if (isNaN(A) || isNaN(E) || isNaN(C)) {
      resultBox.textContent = '请输入有效的数字';
      return;
    }

    if (A === 0) {
      resultBox.textContent = 'A 不能为 0（否则不是二次方程）';
      return;
    }

    const discriminant = E * E - 4 * A * C;
    if (discriminant < 0) {
      resultBox.textContent = `判别式 Δ = ${discriminant.toFixed(4)} < 0，无实数解`;
      return;
    }

    const sqrtD = Math.sqrt(discriminant);
    const y1 = (-E + sqrtD) / (2 * A);
    const y2 = (-E - sqrtD) / (2 * A);

    resultBox.innerHTML = `
      Δ = ${discriminant.toFixed(4)}<br>
      y₁ = ${y1.toFixed(4)}<br>
      y₂ = ${y2.toFixed(4)}
    `;
  }

  // 事件绑定
  function bindEvents() {
    const toggleBtn = document.getElementById('geo-toggle');
    const warningBox = document.getElementById('singular-warning');
    const solveBtn = document.getElementById('solve-btn');
    const resetBtn = document.getElementById('reset-solver');
    const aInput = document.getElementById('coef-a');
    const eInput = document.getElementById('coef-e');
    const cInput = document.getElementById('coef-c');

    if (toggleBtn) {
      toggleBtn.addEventListener('click', () => {
        if (state.isLinear) {
          initSensors();
          toggleBtn.textContent = '切换为线性排列';
          if (warningBox) warningBox.hidden = true;
        } else {
          setLinearArray();
          toggleBtn.textContent = '切换为任意分布';
          if (warningBox) warningBox.hidden = false;
        }
        drawGeometry();
      });
    }

    if (solveBtn) {
      solveBtn.addEventListener('click', solveQuadratic);
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', () => {
        if (aInput) aInput.value = 1;
        if (eInput) eInput.value = -2;
        if (cInput) cInput.value = -3;
        solveQuadratic();
      });
    }

    // 键盘支持
    if (aInput) aInput.addEventListener('change', solveQuadratic);
    if (eInput) eInput.addEventListener('change', solveQuadratic);
    if (cInput) cInput.addEventListener('change', solveQuadratic);
  }

  // 初始化
  function init() {
    initSensors();
    drawGeometry();
    renderTable();
    bindEvents();
    solveQuadratic(); // 初始计算
  }

  // 等待 DOM 加载
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
